import { Request, Response, Router } from "express";
import { CatalogueService } from "../application/catalogue-service";
import { CreateProductDto, PlaceOrderDto } from "../application/dtos";
import { OrderService } from "../application/order-service";
import { DomainError, NotFoundError } from "../domain/errors";
import { OrderState, orderStates } from "../domain/order";

export class OrderController {
  public constructor(
    private readonly catalogue: CatalogueService,
    private readonly orders: OrderService,
  ) {}

  public routes(): Router {
    const router = Router();
    router.post("/products", this.handle((request) => this.catalogue.addProduct(request.body as CreateProductDto), 201));
    router.get("/products", this.handle(() => this.catalogue.listProducts()));
    router.post("/orders", this.handle((request) => this.orders.placeOrder(request.body as PlaceOrderDto), 201));
    router.get("/orders", this.handle((request) => this.orders.listOrders(this.stateFrom(request))));
    router.get("/orders/:id", this.handle((request) => this.orders.getOrder(this.idFrom(request))));
    router.post("/orders/:id/pay", this.transition("paid"));
    router.post("/orders/:id/pack", this.transition("packed"));
    router.post("/orders/:id/ship", this.transition("shipped"));
    router.post("/orders/:id/deliver", this.transition("delivered"));
    router.post("/orders/:id/cancel", this.handle((request) => this.orders.cancelOrder(this.idFrom(request))));
    return router;
  }

  private transition(target: "paid" | "packed" | "shipped" | "delivered") {
    return this.handle((request) => this.orders.advanceOrder(this.idFrom(request), target));
  }

  private idFrom(request: Request): string {
    const value = request.params.id;
    if (typeof value !== "string") throw new DomainError("Order id is required");
    return value;
  }

  private stateFrom(request: Request): OrderState | undefined {
    const value = request.query.state;
    if (value === undefined) return undefined;
    if (typeof value !== "string" || !orderStates.includes(value as OrderState)) {
      throw new DomainError("state must be a valid order state");
    }
    return value as OrderState;
  }

  private handle(action: (request: Request) => unknown, successStatus = 200) {
    return (request: Request, response: Response): void => {
      try {
        response.status(successStatus).json(action(request));
      } catch (error: unknown) {
        if (error instanceof NotFoundError) response.status(404).json({ error: error.message });
        else if (error instanceof DomainError) response.status(409).json({ error: error.message });
        else response.status(500).json({ error: "Unexpected server error" });
      }
    };
  }
}

